using System;
using System.Collections.Generic;
using Astrea;
using Astrea.BattleActions;
using UnityEngine;

[CreateAssetMenu(fileName = "RunStatsData", menuName = "Data/RunStatsData")]
public class RunStatsData : ScriptableObject
{
	[Serializable]
	public class RunData
	{
		public enum RunTypeEnum
		{
			None,
			DailyRun,
			ModdedRun
		}

		public string playedDate;

		public string runTime;

		public string character;

		public string winLose;

		public string difficulty;

		public List<string> path;

		public List<string> blessings;

		public RuntimeCompanionSaveList sentinels;

		public DiceInventorySave diceInventorySave;

		public int runScoreXP;

		public int anomalyLevel;

		public int astreaLevel;

		public RuneSaves runeSaves;

		public List<string> modifiersList;

		public RunTypeEnum runType;

		public RunData(float runTime, string character, string winLose, string difficulty, List<string> path, List<string> blessings, RuntimeCompanionSaveList sentinels, DiceInventorySave diceInventorySave, int runScoreXP, int anomalyLevel, int astreaLevel, RuneSaves runeSaves = null, List<string> modifiersList = null, RunTypeEnum runType = RunTypeEnum.None)
		{
			playedDate = DateTime.Now.ToString("dd-MM-yyyy - HH:mm");
			TimeSpan timeSpan = TimeSpan.FromSeconds(runTime);
			this.runTime = $"{timeSpan.Hours}h {timeSpan.Minutes}m {timeSpan.Seconds}s";
			this.character = character;
			this.winLose = winLose;
			this.difficulty = difficulty;
			this.path = path;
			this.blessings = blessings;
			this.sentinels = sentinels;
			this.diceInventorySave = diceInventorySave;
			this.runScoreXP = runScoreXP;
			this.anomalyLevel = anomalyLevel;
			this.astreaLevel = astreaLevel;
			this.runeSaves = runeSaves;
			this.modifiersList = modifiersList;
			this.runType = runType;
		}
	}

	public List<RunData> datas;
}
